// Bubble Sort implementation
function bubbleSort(arr) {
  const n = arr.length;

  for (let i = 0; i < n; i++) {
    let swapped = false;

    for (let j = 0; j < n - i - 1; j++) {
      if (arr[j] > arr[j + 1]) {
        // Swap
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
        swapped = true;
      }
    }

    if (!swapped) {
      break; 
    }
  }

  return arr;
}

// Example usage
const arr = [64, 34, 25, 12, 22, 11, 90];
console.log('Original:', arr);
bubbleSort(arr);
console.log('Sorted:', arr); 
// [11, 12, 22, 25, 34, 64, 90]
